/bin/bash -c "node --input-type=module <<'NODE'
import { checkout } from './client.mjs'
import { startOrderServer } from './server.mjs'

const { server, url } = await startOrderServer()
const samples = []
try {
  process.env.EXTERNAL_DELAY_MS = '80'
  await checkout(url)

  for (let index = 0; index < 7; index += 1) {
    for (const externalDelayMs of [80, 0]) {
      process.env.EXTERNAL_DELAY_MS = String(externalDelayMs)
      const { body, totalMs } = await checkout(url)
      const externalMs = body.phases.externalMs
      const localMs = body.phases.localMs
      samples.push({
        externalDelayMs,
        totalMs,
        externalMs,
        localMs,
        transportAndJsonMs: totalMs - externalMs - localMs,
        itemCount: body.items.length,
      })
    }
  }

  const round = (value) => Number(value.toFixed(3))
  const aggregate = (values) => {
    const sorted = [...values].sort((a, b) => a - b)
    return {
      median: round(sorted[Math.floor(sorted.length / 2)]),
      min: round(sorted[0]),
      max: round(sorted[sorted.length - 1]),
    }
  }
  const summarized = [80, 0].map((externalDelayMs) => {
    const group = samples.filter((sample) => sample.externalDelayMs === externalDelayMs)
    return {
      externalDelayMs,
      count: group.length,
      totalMs: aggregate(group.map((sample) => sample.totalMs)),
      externalMs: aggregate(group.map((sample) => sample.externalMs)),
      localMs: aggregate(group.map((sample) => sample.localMs)),
      transportAndJsonMs: aggregate(group.map((sample) => sample.transportAndJsonMs)),
      items: group.map((sample) => sample.itemCount),
    }
  })

  console.log(JSON.stringify({
    node: process.version,
    platform: process.platform,
    arch: process.arch,
    summary: summarized,
    raw: samples.map((sample) => Object.fromEntries(
      Object.entries(sample).map(([key, value]) => [key, typeof value === 'number' ? round(value) : value]),
    )),
  }, null, 2))
} finally {
  await new Promise((resolve) => server.close(resolve))
}
NODE"

